    update public.academy_quiz_questions set options = '["Convention: the industry standardised the order in 1975, and reviewers expect to see it followed.", "The grading form presents the fields in that order.", "Each step consumes the previous one''s output, so rearranging breaks inputs.", "Software menus in the standard interpretation packages enforce the sequence mechanically."]'::jsonb
     where app_slug = 'porepressure' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-the-prognosis-workflow' and ord = 15;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'answer-length recut, porepressure refused: intermediate module m06-the-prognosis-workflow ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'porepressure';
  if v_total <> 396 then raise exception 'answer-length recut, porepressure refused: the course holds % questions, expected 396', v_total; end if;
  raise notice 'answer-length recut, porepressure: % of 50 rows updated, the rest already carried the recut text', v_updated;
end $$;
